def cards(*items):
 return '<div class="cards">'+''.join(f'<article class="card"><span class="card-index">{i:02}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(items,1))+'</div>'
def call(text): return f'<p class="callout">{text}</p>'
def reveal(title,text): return f'<details><summary>{title}</summary><p>{text}</p></details>'
def flow(*items): return '<ol class="flow">'+''.join(f'<li><span>{i:02}</span>{x}</li>' for i,x in enumerate(items,1))+'</ol>'
def source_links(ids): return ' · '.join(f'<a href="{refs[x][1]}" target="_blank" rel="noopener">{x}<span class="sr-only"> {E(refs[x][0])} (opens new tab)</span></a>' for x in ids)
def reflist(ids=None):
 return '<ol class="references">'+''.join(f'<li><b>{k}</b> <a href="{v[1]}" target="_blank" rel="noopener">{E(v[0])}</a></li>' for k,v in refs.items() if ids is None or k in ids)+'</ol>'

