questions=[]
def q(id,track,domain,question,options,correct,why,slide_num,ids):
 questions.append(dict(id=id,track=track,domain=domain,question=question,options=options,correct=correct,rationales=why,slide=slide_num,refs=ids))
q('C1','shared','RVUs & attribution','An MFM contract explicitly credits work RVUs. Which measure belongs in that productivity ledger?',
 ['Total RVUs including practice expense','Work RVUs credited under the contract','The amount the payer collected from the patient','The Medicare conversion factor'],1,
 ['Total RVUs include components outside this stated contract.','Correct: the contract specifies work RVUs and its crediting rules.','Patient payments are collections, not work RVUs.','The conversion factor converts adjusted RVUs to a fee-schedule amount.'],4,['R1'])
q('C2','shared','RVUs & attribution','A fictional contract pays $55 per credited wRVU with no threshold. A visit receives 2 wRVUs. What compensation follows from these assumptions?',
 ['$66.80','$133.60','$110.00','$55.00'],2,
 ['This substitutes the rounded Medicare CF for the contract rate.','This uses the slide’s separate payment example.','Correct: 2 × $55 = $110. The assumptions exclude thresholds or other adjustments.','This credits one wRVU rather than two.'],7,['R1','R6'])
q('C3','shared','E/M & payer rules','A Medicaid patient is referred for an MFM opinion about maternal disease. What is the next coding step?',
 ['Automatically use an outpatient consultation code','Use the highest new-patient code','Apply Medicare consultation policy to every Medicaid plan','Check this payer’s code recognition and documentation requirements'],3,
 ['Referral alone does not establish payer recognition.','Neither patient status nor level is established by the referral.','Medicare policy is not a universal Medicaid rule.','Correct: identify the plan’s policy before selecting the E/M family.'],8,['R2'])
q('C4','shared','E/M & payer rules','A stable patient’s chart carries a high-risk pregnancy diagnosis. What best supports office E/M level selection?',
 ['Documented MDM or qualifying clinician time','The high-risk diagnosis alone','The length of the copied problem list','The number of ultrasound images'],0,
 ['Correct: evaluate the work supported by today’s record.','A risk label does not establish a complete E/M level.','Copied text is not evidence of work addressed today.','Image count is not an office E/M leveling criterion.'],10,['R12','R17'])
q('C5','shared','E/M & payer rules','An MFM clinician spends 35 qualifying minutes on E/M and 10 additional minutes on separately billed scan interpretation. How much time enters the E/M calculation?',
 ['45 minutes','10 minutes','35 minutes','All time the patient spends in the clinic'],2,
 ['This double counts separately reported work.','This counts only the excluded service.','Correct: count the 35 eligible E/M minutes.','Waiting and staff time do not become clinician E/M time.'],12,['R13'])
q('C6','shared','Imaging & co-management','After a fetal anatomy scan, the physician only provides the explanation ordinarily included with the imaging service. What is the best billing conclusion?',
 ['Every scan also supports a level-3 visit','A separate E/M service is not established by this description','Modifier 25 creates a separate visit','A second diagnosis guarantees E/M payment'],1,
 ['No independent E/M work has been established.','Correct: routine scan-related work alone does not show separate E/M.','A modifier describes work; it does not create it.','Diagnosis count cannot substitute for a separate service.'],13,['R15'])
q('C7','shared','Imaging & co-management','Another practice provides routine prenatal care while MFM manages a complication. How should the team assess billing?',
 ['All MFM services are included in the other practice’s global fee','All MFM services are separately payable','Use a global delivery code for every MFM visit','Clarify care responsibilities and payer/global-package rules'],3,
 ['This may conceal eligible separate work.','This may improperly unbundle care.','The MFM visit does not establish delivery/global services.','Correct: determine which services were supplied and how the payer treats them.'],17,['R7'])
q('C8','shared','RVUs & attribution','An MFM claim was paid correctly, but the clinician’s production report lacks credit. What should happen first?',
 ['Reconcile rendering identity and contract credit rules','Submit the paid claim again','Add modifier 59 to generate credit','Assume the payer owes more'],0,
 ['Correct: investigate the internal attribution mismatch.','Duplicate submission does not fix the productivity ledger.','Modifier 59 does not assign employment credit.','A crediting issue does not establish payer underpayment.'],25,['R1'])
q('P1','physician','Imaging & co-management','The hospital furnished ultrasound equipment and acquisition. The MFM physician furnished only interpretation and report. Which approach is appropriate?',
 ['Bill global imaging because the report is signed','Bill only the technical component','Assess professional-component billing under the arrangement','Add modifier 25 to the imaging code'],2,
 ['Signing does not establish entitlement to both components.','The physician furnished professional interpretation, not acquisition.','Correct: verify component eligibility and the billing arrangement.','Modifier 25 describes qualifying E/M, not imaging ownership.'],15,['R6'])
q('P2','physician','Imaging & co-management','FGR ultrasound is followed by a separately documented management visit. What is the strongest approach to E/M billing?',
 ['Add modifier 25 without reviewing the note','Support the separate service and verify payer modifier requirements','Include scan interpretation time in E/M','Use a different diagnosis solely to obtain payment'],1,
 ['The record must support separate work.','Correct: the service and policy determine the claim.','Separately reported scan time must be excluded.','Diagnosis manipulation does not establish eligibility.'],14,['R15','R13'])
q('P3','physician','Team billing','A physician co-signs an APP’s Medicare office note but performs no additional work. Incident-to requirements have not been established. What is correct?',
 ['The signature alone supports physician billing','This is automatically a split/shared office visit','The highest clinician credential determines billing','The team must establish a valid pathway from the actual work'],3,
 ['A signature alone does not establish the required service or supervision conditions.','Medicare office visits are not split/shared visits.','Credential hierarchy does not replace billing requirements.','Correct: assess direct APP billing or another pathway only if its conditions are met.'],21,['R5','R11'])
q('P4','physician','Imaging & co-management','A fetal imaging claim has a procedure-to-procedure edit. What is the best next action?',
 ['Check the current pair, modifier indicator and documented circumstances','Append modifier 59 to every denied imaging line','Assume separate diagnoses override the edit','Replace the performed service with a higher-valued code'],0,
 ['Correct: determine whether a supported modifier exception is available.','A denial is not evidence of distinct services.','Separate diagnoses alone do not satisfy modifier requirements.','Code the work performed, not a payment target.'],16,['R9','R16'])
q('A1','app','Team billing','An enrolled MFM NP personally performs a medically necessary office visit within scope. Incident-to criteria are not met. What pathway may be available?',
 ['No professional service can be billed','Only billing through the physician’s NPI','Direct NP billing if the service meets payer requirements','Automatic global maternity billing'],2,
 ['Failure of incident-to eligibility does not eliminate direct billing eligibility.','A physician NPI is not universally required.','Correct: eligible personally furnished NP services can be directly billed.','This encounter does not establish a global maternity service.'],18,['R3'])
q('A2','app','Team billing','An NP evaluates a new concern during established diabetes follow-up. The physician has not addressed that concern. What should the NP do about billing?',
 ['Reassess incident-to eligibility and document the actual work','Use incident-to because the patient is established','Obtain only a co-signature and assume eligibility','Ignore the new concern to preserve the original billing plan'],0,
 ['Correct: evaluate the new problem clinically and verify the appropriate billing pathway.','Patient status alone is insufficient.','A co-signature does not establish the required treatment involvement.','Patient needs determine care; the billing plan must follow it.'],20,['R14','R5'])
q('A3','app','Team billing','Which statement best describes Medicare’s typical direct professional-service allowed amounts for NPs/PAs and CNMs?',
 ['Every APP receives 85% under every payer','NP/PA generally 85%; eligible CNM services 100% of the physician fee-schedule basis','All receive 100% if a physician is in the building','The percentage equals the clinician’s take-home pay'],1,
 ['Both profession and payer matter.','Correct: these are Medicare allowed-amount rules, not universal payer or salary rules.','Availability alone does not change the direct-billing percentage.','Employment compensation and allowed amounts are different measures.'],19,['R3','R4','R10'])
q('A4','app','Team billing','An APP and physician from the same group share an eligible hospital outpatient E/M encounter. What determines the Medicare split/shared billing clinician?',
 ['Who opened the chart first','Who has the higher salary','Who co-signed last','Who performed the substantive portion under the applicable rule'],3,
 ['Chart-opening order is not the criterion.','Compensation does not determine the renderer.','Signature sequence does not establish substantive work.','Correct: verify substantive MDM or more than half of distinct time for eligible noncritical E/M, plus documentation and FS requirements.'],22,['R11','R2'])

CSS = (ROOT/'style.css').read_text(encoding='utf-8')
def page(title,body,script='',description='MFM physician and APP education on RVUs, E/M, fetal imaging and team billing.'):
 filename = 'answer-key.html' if 'Answer Key' in title else ('quiz.html' if 'Quiz' in title else 'index.html')
 canonical = 'https://openmfm.org/decks/rvu-medical-billing-mfm/' + filename
 metadata = '<!-- openmfm-seo-injected --><link rel="canonical" href="'+canonical+'"><meta property="og:type" content="website"><meta property="og:title" content="'+E(title)+'"><meta property="og:description" content="'+E(description)+'"><meta property="og:url" content="'+canonical+'"><meta property="og:image" content="https://openmfm.org/og-image.png"><meta name="twitter:card" content="summary_large_image"><meta name="author" content="Dr. Chukwuma Onyeije, MD"><script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@type':'LearningResource','name':title,'description':description,'url':canonical,'learningResourceType':'Quiz' if filename=='quiz.html' else 'Presentation','audience':{'@type':'Audience','audienceType':'MFM physicians and MFM APPs'},'publisher':{'@type':'Organization','name':'OpenMFM','url':'https://openmfm.org'},'dateModified':'2026-11-24'})+'</script>'
 return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#09121d"><title>'+E(title)+' | OpenMFM</title><meta name="description" content="'+E(description)+'"><style>'+CSS+'</style>'+metadata+'</head><body><a class="skip" href="#main">Skip to content</a>'+body+('<script>'+script+'</script>' if script else '')+'</body></html>'
def header(quiz=False):
 return '<header class="topbar"><a class="brand" href="index.html">Open<span>MFM</span><small>Clinical practice education</small></a><nav aria-label="Resources"><!-- openmfm-footer-injected --><a class="button" href="/library">Library</a>'+('<a class="button" href="index.html">Presentation</a>' if quiz else '<button id="refs-open">References</button>')+'<a class="button" href="'+('answer-key.html' if quiz else 'quiz.html')+'">'+('Answer key' if quiz else 'Quiz tracks')+'</a><button class="print" onclick="window.print()">Print / PDF</button></nav></header>'

deck = header()+'<main id="main">'
for n,s in enumerate(slides,1):
 deck+=f'<section class="slide {"title-slide" if n==1 else ""} {"ref-slide" if n==28 else ""}" id="slide-{n}" aria-labelledby="title-{n}"><div class="slide-heading"><p class="eyebrow">{E(s["chapter"])}</p><h{1 if n==1 else 2} id="title-{n}" tabindex="-1">{E(s["title"])}</h{1 if n==1 else 2}><p class="subtitle">{E(s["sub"])}</p></div><div class="content">{s["content"]}</div><footer class="slide-footer"><span>OpenMFM · 2026 service-year edition</span><span>{source_links(s["refs"])}</span><span>{n:02} / 28</span></footer></section>'
deck+='</main><div class="controls" hidden><button id="previous" aria-label="Previous slide">← Back</button><label class="sr-only" for="jump">Go to slide</label><select id="jump">'+''.join(f'<option value="{n}">{n:02} · {E(s["title"])}</option>' for n,s in enumerate(slides,1))+'</select><span id="counter" aria-live="polite"></span><button id="next" class="primary" aria-label="Next slide">Next →</button><progress id="progress" max="28" value="1" aria-label="Presentation progress"></progress></div><dialog id="reference-panel" aria-labelledby="ref-title"><div class="dialog-head"><h2 id="ref-title">Sources & policy versions</h2><button id="refs-close">Close</button></div><p>Reviewed November 23, 2026. Links open in a new tab.</p>'+reflist()+'</dialog><noscript><p class="callout">JavaScript is disabled. All slides remain readable; use the browser’s print function.</p></noscript>'
deckjs=r'''
document.documentElement.classList.add('enhanced');
const slides=[...document.querySelectorAll('.slide')], prev=document.querySelector('#previous'), next=document.querySelector('#next'), jump=document.querySelector('#jump'), panel=document.querySelector('#reference-panel');
let current=0;
function show(index,focus=false){current=Math.max(0,Math.min(slides.length-1,index));slides.forEach((s,i)=>s.hidden=i!==current);prev.disabled=current===0;next.disabled=current===slides.length-1;jump.value=current+1;document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;document.querySelector('#progress').value=current+1;if(focus){window.scrollTo(0,0);slides[current].querySelector('h1,h2').focus({preventScroll:true});}}
function go(i){const n=Math.max(0,Math.min(slides.length-1,i));if(location.hash===`#slide-${n+1}`)show(n,true);else location.hash=`slide-${n+1}`;}
function fromHash(focus){const m=location.hash.match(/^#slide-(\d+)$/);show(m?Number(m[1])-1:0,focus);}
document.querySelector('.controls').hidden=false;fromHash(false);addEventListener('hashchange',()=>fromHash(true));
prev.onclick=()=>go(current-1);next.onclick=()=>go(current+1);jump.onchange=()=>go(Number(jump.value)-1);
document.addEventListener('keydown',e=>{if(panel.open||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.target.closest('input,select,textarea,button,a,summary'))return;const actions={ArrowRight:current+1,ArrowLeft:current-1,PageDown:current+1,PageUp:current-1,Home:0,End:slides.length-1};if(e.key in actions){e.preventDefault();go(actions[e.key]);}});
let touch;document.querySelector('main').addEventListener('touchstart',e=>{if(e.touches.length===1&&!e.target.closest('input,button,a,summary,select'))touch={x:e.touches[0].clientX,y:e.touches[0].clientY};else touch=null;},{passive:true});
document.querySelector('main').addEventListener('touchend',e=>{if(!touch)return;const dx=e.changedTouches[0].clientX-touch.x,dy=e.changedTouches[0].clientY-touch.y;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)go(current+(dx<0?1:-1));touch=null;},{passive:true});
document.querySelector('#refs-open').onclick=()=>panel.showModal();document.querySelector('#refs-close').onclick=()=>panel.close();
function calculate(){const val=id=>{const el=document.getElementById(id);return el.value.trim()!==''&&el.validity.valid?Number(el.value):null;};const r=val('rvu'),w=val('work'),c=val('rate');const usd=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});document.querySelector('#payment').textContent=r===null?'Enter a valid value':usd(r*33.40);document.querySelector('#pay').textContent=w===null||c===null?'Enter valid values':usd(w*c);}
['rvu','work','rate'].forEach(id=>document.getElementById(id).addEventListener('input',calculate));
let opened=[];addEventListener('beforeprint',()=>{opened=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true);});addEventListener('afterprint',()=>document.querySelectorAll('details').forEach((d,i)=>d.open=opened[i]));
'''
(ROOT/'index.html').write_text(page('RVUs & Medical Billing in the MFM Clinic',deck,deckjs),encoding='utf-8')
(ROOT/'quiz-data.json').write_text(json.dumps(questions,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')

quiz=header(True)+'''<main id="main" class="quiz-main"><p class="eyebrow">Apply what you learned</p><h1>MFM billing.<br><em>Your role. Your decisions.</em></h1><p class="subtitle">Eight shared questions plus four role-specific cases. Explanations, source links and focused review follow every answer.</p><section id="setup" class="card"><h2>Choose a track</h2><p>Fictional cases • No patient information collected • No CME credit</p><div class="track-grid"><button class="track" data-track="physician"><strong>MFM physician</strong><span>12 questions · imaging, E/M and attribution</span></button><button class="track" data-track="app"><strong>MFM APP</strong><span>12 questions · direct billing and collaboration</span></button><button class="track" data-track="all"><strong>Both tracks</strong><span>All 16 questions · team learning</span></button></div><p class="small">Answers stay in memory only. Reloading clears your attempt. You can revisit this screen to change tracks.</p></section><section id="quiz" class="quiz-shell" hidden aria-label="Assessment"><div class="quiz-top"><span id="track-label"></span><span id="question-count"></span></div><progress id="quiz-progress" value="0" max="12" aria-label="Questions completed"></progress><form id="question-form"><fieldset><legend id="question-title" tabindex="-1"></legend><p id="domain" class="eyebrow"></p><div id="options"></div></fieldset><div class="actions"><button class="primary" id="submit" type="submit" disabled>Check answer</button><button id="advance" type="button" hidden>Next question →</button></div></form><div id="feedback" class="feedback" tabindex="-1" hidden></div></section><section id="results" class="card results" hidden tabindex="-1"></section><div class="actions"><button id="change-track" hidden>Choose another track</button></div><p class="small">Policy basis: 2026 services. Verify payer and service-date requirements for real claims. A score measures this learning exercise, not clinical or coding credentials.</p><noscript><p class="callout">The interactive quiz requires JavaScript. <a href="answer-key.html">Read the printable questions and explanations.</a></p></noscript></main>'''
quiz = quiz.replace('<button id="advance" type="button" hidden>Next question →</button>', '').replace('<div id="feedback" class="feedback" tabindex="-1" hidden></div>', '<div id="feedback" class="feedback" tabindex="-1" hidden></div><div class="quiz-next"><button id="advance" type="button" hidden>Next question →</button></div>')
quizjs='const QUESTIONS='+json.dumps(questions,ensure_ascii=False)+';\nconst REFS='+json.dumps(refs,ensure_ascii=False)+';\n'+r'''
const $=s=>document.querySelector(s);let pool=[],answers=[],pos=0,track='all',retryMode=false;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={physician:'MFM physician',app:'MFM APP',all:'Both tracks'};
function sources(q){return q.refs.map(r=>`<a href="${REFS[r][1]}" target="_blank" rel="noopener">${r}: ${escapeHTML(REFS[r][0])}</a>`).join('');}
function start(t,subset=null){track=t;retryMode=!!subset;pool=subset||QUESTIONS.filter(q=>q.track==='shared'||t==='all'||q.track===t);answers=[];pos=0;$('#setup').hidden=true;$('#results').hidden=true;$('#quiz').hidden=false;$('#change-track').hidden=false;$('#track-label').textContent=names[t]+(retryMode?' · Missed-question practice':'');render();}
function render(){const q=pool[pos];$('#question-title').textContent=q.question;$('#question-count').textContent=`${pos+1} / ${pool.length}`;$('#domain').textContent=q.domain+' · '+(q.track==='shared'?'Shared core':names[q.track]);$('#quiz-progress').max=pool.length;$('#quiz-progress').value=pos;$('#options').innerHTML=q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}"><span><b>${String.fromCharCode(65+i)}.</b> ${escapeHTML(o)}</span></label>`).join('');$('#submit').hidden=false;$('#submit').disabled=true;$('#advance').hidden=true;$('#advance').textContent=pos===pool.length-1?'View results →':'Next question →';$('#feedback').hidden=true;$('#feedback').innerHTML='';$('#question-title').focus();}
$('#options').addEventListener('change',()=>$('#submit').disabled=false);
$('#question-form').addEventListener('submit',e=>{e.preventDefault();if(answers[pos]!==undefined)return;const selected=document.querySelector('input[name=answer]:checked');if(!selected)return;const answer=Number(selected.value),q=pool[pos];answers[pos]=answer;document.querySelectorAll('input[name=answer]').forEach(r=>r.disabled=true);$('#submit').hidden=true;$('#advance').hidden=false;$('#quiz-progress').value=pos+1;document.querySelectorAll('.option').forEach((el,i)=>{if(i===q.correct)el.classList.add('correct');else if(i===answer)el.classList.add('incorrect');});$('#feedback').innerHTML=`<h2>${answer===q.correct?'Correct':'Review this decision'}</h2><p><strong>Best answer: ${String.fromCharCode(65+q.correct)}. ${escapeHTML(q.options[q.correct])}</strong></p><ol class="rationales">${q.rationales.map((r,i)=>`<li><b>${String.fromCharCode(65+i)}:</b> ${escapeHTML(r)}</li>`).join('')}</ol><a href="index.html#slide-${q.slide}" target="_blank" rel="noopener">Review slide ${q.slide} (new tab)</a><div class="source-list">${sources(q)}</div>`;$('#feedback').hidden=false;$('#feedback').focus();});
$('#advance').onclick=()=>{if(++pos<pool.length)render();else finish();};
function finish(){const score=pool.filter((q,i)=>answers[i]===q.correct).length;const domains={};pool.forEach((q,i)=>{domains[q.domain]??={n:0,right:0};domains[q.domain].n++;if(answers[i]===q.correct)domains[q.domain].right++;});$('#quiz').hidden=true;const res=$('#results');res.hidden=false;res.innerHTML=`<p class="eyebrow">${names[track]}${retryMode?' · Practice result':''}</p><h2>Turn the result into a review plan.</h2><p class="metric">${score} / ${pool.length} <span class="small">(${Math.round(score/pool.length*100)}%)</span></p><p>${score===pool.length?'Every decision was correct in this attempt.':'Review the missed decisions and their source policies.'}</p><div class="domain-grid">${Object.entries(domains).map(([d,v])=>`<div class="card"><h3>${d}</h3><b>${v.right} / ${v.n}</b></div>`).join('')}</div><div class="actions no-print"><button id="retry" ${score===pool.length?'disabled':''}>Retry missed questions</button><button id="restart">Restart full track</button><button onclick="window.print()">Print results</button></div><h3>Answer review</h3>${pool.map((q,i)=>`<details class="review"><summary>${answers[i]===q.correct?'Correct':'Missed'} · ${escapeHTML(q.question)}</summary><p>Your answer: ${escapeHTML(q.options[answers[i]])}</p><p><strong>Best answer: ${escapeHTML(q.options[q.correct])}</strong></p><p>${escapeHTML(q.rationales[q.correct])}</p><p>${answers[i]!==q.correct?escapeHTML(q.rationales[answers[i]]):''}</p><a href="index.html#slide-${q.slide}" target="_blank" rel="noopener">Review slide ${q.slide}</a><div class="source-list">${sources(q)}</div></details>`).join('')}`;$('#retry').onclick=()=>{const missed=pool.filter((q,i)=>answers[i]!==q.correct);start(track,missed);};$('#restart').onclick=()=>start(track);res.focus();}
document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>start(b.dataset.track));$('#change-track').onclick=()=>{$('#quiz').hidden=true;$('#results').hidden=true;$('#setup').hidden=false;$('#change-track').hidden=true;document.querySelector('[data-track]').focus();history.replaceState(null,'',location.pathname);};
const requested=new URLSearchParams(location.search).get('track');if(['physician','app','all'].includes(requested))start(requested);
let opened=[];addEventListener('beforeprint',()=>{opened=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true);});addEventListener('afterprint',()=>document.querySelectorAll('details').forEach((d,i)=>d.open=opened[i]));
'''
(ROOT/'quiz.html').write_text(page('MFM Billing Quiz: Physician & APP Tracks',quiz,quizjs),encoding='utf-8')
key=header(True)+'<main id="main" class="answer-key"><p class="eyebrow">Facilitator resource</p><h1>MFM billing: answer key</h1><p>2026 service-year edition · 16 questions · Reviewed November 23, 2026</p><p>Physician track: C1–C8 + P1–P4. APP track: C1–C8 + A1–A4. Fictional cases; no CME credit.</p>'
for qn in questions:
 key+=f'<article class="key-question"><p class="eyebrow">{qn["id"]} · {qn["track"]} · {qn["domain"]}</p><h2>{E(qn["question"])}</h2><ol type="A">'+''.join(f'<li><strong>{E(o)}</strong><p>{E(qn["rationales"][i])}</p></li>' for i,o in enumerate(qn['options']))+f'</ol><p class="callout">Best answer: {chr(65+qn["correct"])} · <a href="index.html#slide-{qn["slide"]}">Review slide {qn["slide"]}</a></p><p>{source_links(qn["refs"])}</p></article>'
key+='<section class="key-references"><h2>References</h2>'+reflist()+'</section></main>'
(ROOT/'answer-key.html').write_text(page('MFM Billing Answer Key',key),encoding='utf-8')
print(f'Built {len(slides)} slides, {len(questions)} questions, and answer key.')
